// UpdateOutputOnly persists the server-owned fields of in that paths names.
// When in.Etag is set the write is guarded server-side, as in Update.
func (r *GraphQLTodoRepository) UpdateOutputOnly(ctx context.Context, in *todov1.Todo, paths []string) (*todov1.Todo, error) {
	if len(paths) == 0 {
		return nil, fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	id, err := r.rowID(ctx, in.GetName())
	if err != nil {
		return nil, err
	}
	patch := todoToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	if in.GetEtag() != "" {
		if _, err := r.Svc.Mutation.Todo.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(in.GetEtag())); err != nil {
			return nil, mapGraphQLErr(err)
		}
		return r.get(ctx, id)
	}
	resp, err := r.Svc.Mutation.Todo.Resource.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
}

// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. The update time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GraphQLTodoRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "calendars", "todos"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	if _, err := r.Svc.Mutation.Todo.Resource.UpdateIfMatch(ctx, id, r.deletePatch(), resourceql.DeleteTime.IsNull(true)); err != nil {
		if errors.Is(err, graphql.ErrConflict) {
			return repox.ErrNotFound
		}
		return mapGraphQLErr(err)
	}
	return nil
}

// deletePatch is the write that soft-deletes a record now: Delete's, and a
// Batch's.
func (r *GraphQLTodoRepository) deletePatch() resourceql.UpdateInput {
	at := time.Now().UTC()
	now := at.Format(time.RFC3339Nano)
	patch := resourceql.UpdateInput{DeleteTime: graphql.Value(now)}
	patch.UpdateTime = graphql.Value(now) // the delete is the record's latest write
	if r.Retention > 0 {
		patch.ExpireTime = graphql.Value(at.Add(r.Retention).Format(time.RFC3339Nano))
	}
	patch.Etag = graphql.Value(repox.NewULID())
	return patch
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GraphQLTodoRepository) Undelete(ctx context.Context, name string) (*todov1.Todo, error) {
	id, err := r.rowID(ctx, name)
	if err != nil {
		return nil, err
	}
	patch := resourceql.UpdateInput{DeleteTime: graphql.Null[string]()}
	patch.UpdateTime = graphql.Value(time.Now().UTC().Format(time.RFC3339Nano))
	patch.ExpireTime = graphql.Null[string]()
	patch.Etag = graphql.Value(repox.NewULID())
	if _, err := r.Svc.Mutation.Todo.Resource.UpdateIfMatch(ctx, id, patch, resourceql.DeleteTime.IsNull(false)); err != nil {
		if !errors.Is(err, graphql.ErrConflict) {
			return nil, mapGraphQLErr(err)
		}
		if _, err := r.get(ctx, id); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, id)
}

// Purge removes the record addressed by its resource name for good.
func (r *GraphQLTodoRepository) Purge(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "calendars", "todos"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	_, err = r.purge(ctx, id, name, true)
	return err
}

// purge removes row id, named name, for good -- unless something still
// refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught
// again from the database's own refusal), or, when askReferrers, a referrer
// in another database or service (r.Refs). A purge never fails, and never
// cascades, because of a referrer. repox.ErrNotFound when there is no such
// row.
func (r *GraphQLTodoRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "the-protobuf-project.org/Todo", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GraphQLTodoRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			id, err := r.rowID(ctx, m.GetName())
			if errors.Is(err, repox.ErrNotFound) {
				continue // gone since the page was read
			}
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, id, m.GetName(), true)
			switch {
			case errors.Is(err, repox.ErrNotFound):
			case err != nil:
				return res, err
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// remove deletes row id with the value-object rows it owns.
func (r *GraphQLTodoRepository) remove(ctx context.Context, id string) error {
	resp, err := r.Svc.Mutation.Todo.Resource.Delete(ctx, id)
	if err != nil {
		return mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return repox.ErrNotFound
	}
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].StartId); id != "" {
			if _, err := r.Svc.Mutation.Todo.CalendarTimes.Delete(ctx, id); err != nil {
				return mapGraphQLErr(err)
			}
		}
	}
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].DueId); id != "" {
			if _, err := r.Svc.Mutation.Todo.CalendarTimes.Delete(ctx, id); err != nil {
				return mapGraphQLErr(err)
			}
		}
	}
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].CompletedId); id != "" {
			if _, err := r.Svc.Mutation.Todo.CalendarTimes.Delete(ctx, id); err != nil {
				return mapGraphQLErr(err)
			}
		}
	}
	dtx := r.Svc.Mutation.Tx()
	{
		rows5, err := r.Svc.Query.Todo.ExtensionProperties.List(ctx, extensionpropertiesql.List().Where(extensionpropertiesql.TodoId.Eq(id)))
		if err != nil {
			return mapGraphQLErr(err)
		}
		for i := range rows5 {
			if id := rows5[i].Id; id != "" {
				got6, err := r.Svc.Query.Todo.ExtensionProperties.Get(ctx, id)
				if err != nil {
					return mapGraphQLErr(err)
				}
				if got6 != nil {
					dtx.Add(r.Svc.Mutation.Todo.ExtensionProperties.DeleteOp(got6.Id, new(extensionpropertiesql.DeleteTodoExtensionPropertiesByIdResponse)))
				}
			}
		}
	}
	if err := dtx.Commit(ctx); err != nil {
		return mapGraphQLErr(err)
	}
	return nil
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GraphQLTodoRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*todov1.Todo, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*todov1.Todo, string, error) {
		return r.List(ctx, "calendars/-", in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ TodoRepository = (*GraphQLTodoRepository)(nil)

// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u         *repox.Unit
	svc       *freebusyql.Service
	retention time.Duration
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateTodo queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateTodo(parent string, in *todov1.Todo) (string, error) {
	r := &GraphQLTodoRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueTodoReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		return r.insertOps(ctx, ops, named, ci)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Todo", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateTodo queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateTodo(in *todov1.Todo, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "calendars", "todos"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLTodoRepository{Svc: b.svc}
	queueTodoReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Todo", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getTodo)})
}

// UpdateTodoWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it inside the batch's request, as UpdateTodo's does.
func (b *graphQLBatch) UpdateTodoWithOutputOnly(in *todov1.Todo, paths, outputPaths []string) {
	if _, err := repox.SplitName(in.GetName(), "calendars", "todos"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLTodoRepository{Svc: b.svc}
	queueTodoReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Todo", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getTodo)})
}

// UpdateTodoOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateTodoOutputOnly(in *todov1.Todo, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "calendars", "todos"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLTodoRepository{Svc: b.svc}
	patch := todoToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Todo", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getTodo)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Todo.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Todo.Resource.UpdateOp(id, patch, new(resourceql.UpdateTodoResourceByIdResponse)))
		return nil, nil
	})
}

// DeleteTodo queues a soft delete. A record already deleted or gone is
// not an error.
func (b *graphQLBatch) DeleteTodo(name string) {
	if _, err := repox.SplitName(name, "calendars", "todos"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLTodoRepository{Svc: b.svc, Retention: b.retention}
	queueTodoDelete(b.u, name, false)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Todo.Resource.UpdateOp(id, r.deletePatch(), new(resourceql.UpdateTodoResourceByIdResponse), resourceql.Update().PreCheck(resourceql.DeleteTime.IsNull(true))))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Todo", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getTodo)})
}

// PurgeTodo queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeTodo(name string) {
	if _, err := repox.SplitName(name, "calendars", "todos"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLTodoRepository{Svc: b.svc, Refs: b.u.Conn().References}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of
	// this database still names fails the commit with
	// repox.ErrForeignKey: the request is one transaction, and the engine
	// cannot skip one of its mutations.
	keep := queueTodoPurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Todo", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getTodo)})
}
